    // everything shines a little by its gloss: metal and bronze most, catching the lamps and the sky
    col += metal * Llamp * a * 0.8 + sheen(N, V, vW, p > 6.5 && p < 7.5 ? 0.6 : metal > 0.5 ? 0.4 : p > 11.5 && p < 13.5 ? 0.03 : 0.08);
    if (glow > 0.0) col = a * mix(0.55, 1.4, glow) * (0.85 + 0.15 * smoothstep(-0.3, 0.6, N.y));
    // where the lamps catch the leaves they turn yellow-green, the undersides glowing
