    lead = max(1.0 - smoothstep(lw * 0.5, lw * 0.5 + px, abs(d - 0.11)), 1.0 - smoothstep(lw * 0.5, lw * 0.5 + px, abs(fract(q.y / 0.2 + q.x * 0.5) - 0.5) * 0.2 - 0.09));
